#include <stdio.h>
#include <string.h>
void badCharHeuristic(const char *pat, int m, int bad[256]){
    for(int i=0;i<256;i++) bad[i]=-1;
    for(int i=0;i<m;i++) bad[(unsigned char)pat[i]]=i;
}
void searchBM(const char *txt, const char *pat){
    int n=(int)strlen(txt), m=(int)strlen(pat);
    int bad[256]; badCharHeuristic(pat,m,bad);
    int s=0;
    printf("文本: %s\n模式: %s\n", txt, pat);
    while(s<=n-m){
        int j=m-1;
        while(j>=0 && pat[j]==txt[s+j]) j--;
        if(j<0){
            printf("坏字符规则命中：模式在文本位置 %d 完整匹配\n", s);
            s += (s+m<n)? m-bad[(unsigned char)txt[s+m]] : 1;
        } else {
            int shift = j - bad[(unsigned char)txt[s+j]];
            printf("失配于模式位 %d(文本字符 '%c')，坏字符右移量 = %d\n",
                   j, txt[s+j], shift>1?shift:1);
            s += (shift>1)? shift : 1;
        }
    }
}
int main(void){
    searchBM("GCATCGCAGAGAGT","GCAGAGAG");
    return 0;
}
